/* eslint-disable max-lines -- generated PNG byte blobs, see header */
/**
 * defaultAssets — baked PNG byte streams for the .pkpass bundle.
 *
 * Generated once from:
 *   * solidarity/Resources/sakura-white.svg (sakura icon, ImageMagick
 *     composited onto rgb(33,150,243) to match Swift PASS_BG_COLOR)
 *   * apps/expo/assets/brand/wordmark.svg   (wordmark, rsvg-convert,
 *     fill #FAFAF9 to match Swift PASS_FG_COLOR)
 *   * solidarity/Resources/{dog,horse,pig,sheep,dove}.png (animal
 *     avatars rescaled to 87x87 over PASS_BG_COLOR)
 *
 * Why baked rather than runtime-rasterised? PassKit refuses passes whose
 * declared asset hashes drift from the manifest, and shipping an SVG-to-
 * PNG renderer in the RN bundle costs ~300 KB. The Swift side has the
 * same tradeoff: PassKitManager+Generation.swift's createLogoImage /
 * createIconImage render once to PNG and never on the hot path.
 *
 * Regenerate from the source SVGs/PNGs (no runtime hot path) with
 *   rsvg-convert -w 29 -h 29  sakura-white.svg | magick - over bg → icon.png
 *   rsvg-convert -w 160 -h 28 wordmark.svg                       → logo.png
 *   magick   {dog,horse,…}.png -resize 87x87 -background PASS_BG -alpha remove
 * then `base64 -i <file>` and chunk to 76 cols, one block per export below.
 */

import { base64Decode, type Animal } from '@solidarity/shared';

