/**
 * Decoded byte streams — exported so callers can pass them around. One pair
 * of icon + logo per PassKit scale (@1x / @2x / @3x). Decoded once at module
 * load so the SHA-1 manifest computation doesn't pay the base64 cost.
 */
export const DEFAULT_ICON_PNG: Uint8Array = base64Decode(ICON_PNG_BASE64);
export const DEFAULT_ICON_AT_2X_PNG: Uint8Array = base64Decode(
  ICON_AT_2X_PNG_BASE64
);
export const DEFAULT_ICON_AT_3X_PNG: Uint8Array = base64Decode(
  ICON_AT_3X_PNG_BASE64
);
export const DEFAULT_LOGO_PNG: Uint8Array = base64Decode(LOGO_PNG_BASE64);
export const DEFAULT_LOGO_AT_2X_PNG: Uint8Array = base64Decode(
  LOGO_AT_2X_PNG_BASE64
);
export const DEFAULT_LOGO_AT_3X_PNG: Uint8Array = base64Decode(
  LOGO_AT_3X_PNG_BASE64
);

/**
 * Animal avatar lookup — keyed by the BusinessCard.animal enum. Each PNG
 * is 87×87 (icon@3x size) so the same byte stream can be reused as the
 * icon at every scale (matches the Swift one-bitmap-per-card approach).
 */
export const ANIMAL_ICON_PNG: Readonly<Record<Animal, Uint8Array>> = {
  dog: base64Decode(ANIMAL_DOG_PNG_BASE64),
  horse: base64Decode(ANIMAL_HORSE_PNG_BASE64),
  pig: base64Decode(ANIMAL_PIG_PNG_BASE64),
  sheep: base64Decode(ANIMAL_SHEEP_PNG_BASE64),
  dove: base64Decode(ANIMAL_DOVE_PNG_BASE64),
};
